import {mountShell} from '../shared/shell.js';
import {escapeHtml as esc,readStore,writeStore,downloadText} from '../shared/utils.js';
import {LIMITS,example,validate,availability,liveState,ancestors,improvements,connect,disconnect,updateNode,addNode,addAlternative,addCommonDependency,removeNode,setOutput} from './engine.js';
import {registerTools} from './webmcp.js';
mountShell({active:'reliability',label:'MODEL 05',title:'A system of almost reliable parts'});
const STORAGE='thinking-lab:reliability:v1';const app=document.querySelector('#app');
const clone=v=>structuredClone(v),pct=p=>`${(p*100).toFixed(2)}%`,pp=p=>`${p<0?'−':'+'}${(Math.abs(p)*100).toFixed(2)} pp`;
let graph=example(),baseline=clone(graph),failed=[],scenario='bess',selected='clock',linkSource=null,commonTargets=null,undo=[],redo=[],message='',isError=false,storageOK=true;
try{const data=readStore(STORAGE,null);if(data){graph=validate(data.graph);baseline=validate(data.baseline);failed=Array.isArray(data.failed)?data.failed:[];availability(graph,failed);scenario=data.scenario==='service'?'service':'bess';selected=graph.nodes.some(n=>n.id===data.selected)?data.selected:graph.output;}}catch{graph=example();baseline=clone(graph);failed=[];selected='clock';}
const node=id=>graph.nodes.find(n=>n.id===id);
const snapshot=()=>clone({graph,baseline,failed,scenario});
function applySnapshot(s){({graph,baseline,failed,scenario}=clone(s));if(!node(selected))selected=graph.output;linkSource=null;commonTargets=null;}
function save(){storageOK=writeStore(STORAGE,{graph,baseline,failed,scenario,selected});}
function announce(text){document.querySelector('#live-status').textContent=text;}
function commit(patch,text='Map updated.'){undo.push(snapshot());undo=undo.slice(-30);redo=[];for(const [key,value] of Object.entries(patch)){if(key==='graph')graph=value;if(key==='failed')failed=value;if(key==='baseline')baseline=value;if(key==='scenario')scenario=value;}failed=failed.filter(id=>graph.nodes.some(n=>n.id===id&&n.kind==='component'));if(!node(selected))selected=graph.output;linkSource=null;commonTargets=null;message=text;isError=false;save();render();announce(`${text} Whole-system availability ${pct(availability(graph,failed))}.`);}
function attempt(action){try{action();}catch(error){message=error.message;isError=true;render();announce(error.message);}}
function dimensions(){return {width:Math.max(1270,...graph.nodes.map(n=>n.x+195)),height:Math.max(430,...graph.nodes.map(n=>n.y+180))};}
function curve(source,target){const a=node(source),b=node(target),x=a.x+166,y=a.y+78,tx=b.x,ty=b.y+78,bend=Math.max(45,Math.min(100,(tx-x)/2));return `M ${x} ${y} C ${x+bend} ${y}, ${tx-bend} ${ty}, ${tx} ${ty}`;}
function edges(live,used){return graph.nodes.flatMap(target=>target.inputs.map(source=>`<g><path class="wire ${!live.states[source]?'blocked':''} ${!used.has(target.id)?'irrelevant':''}" d="${curve(source,target.id)}" marker-end="url(#arrow-${!live.states[source]?'down':'up'})"/><path class="wire-hit" d="${curve(source,target.id)}" data-edge-source="${esc(source)}" data-edge-target="${esc(target.id)}" tabindex="0" role="button" aria-label="Remove dependency from ${esc(node(source).label)} to ${esc(target.label)}"><title>Remove ${esc(node(source).label)} → ${esc(target.label)}</title></path></g>`)).join('');}
function renderNodes(live,used){return graph.nodes.map(n=>{const ownFailed=failed.includes(n.id),blocked=!live.states[n.id],shared=graph.nodes.filter(t=>t.inputs.includes(n.id)).length>1;return `<section class="node ${selected===n.id?'selected':''} ${graph.output===n.id?'output':''} ${ownFailed?'failed':blocked?'blocked':''} ${!used.has(n.id)?'irrelevant':''} ${commonTargets?.includes(n.id)?'common-picked':''}" data-node="${esc(n.id)}" style="left:${n.x}px;top:${n.y}px" aria-label="${esc(n.label)}${ownFailed?', held failed':blocked?', blocked by dependency':''}">${graph.output===n.id?'<span class="output-badge">SYSTEM OUTPUT</span>':''}<button class="node-handle" data-select="${esc(n.id)}" aria-pressed="${selected===n.id}" aria-label="Select or drag ${esc(n.label)}. Arrow keys move it."><span class="node-name">${esc(n.label)}</span><span class="node-type">${n.kind==='gate'?(n.gate==='AND'?'ALL inputs':'ANY input'):shared?'Shared component':'Component'}</span></button><div class="node-meta"><i class="dot" aria-hidden="true"></i>${n.kind==='component'?`${(n.p*100).toFixed(1)}% available`:n.inputs.length?`${n.inputs.filter(id=>live.states[id]).length} of ${n.inputs.length} inputs available`:'No inputs connected'}</div>${n.kind==='component'?`<button class="fail-toggle" data-fail="${esc(n.id)}" aria-pressed="${ownFailed}">${ownFailed?'Restore component':'Inject failure'}</button>`:`<div class="gate-state">${blocked?'Gate cannot pass':'Gate can pass'}</div>`}<button class="port in ${linkSource&&linkSource!==n.id?'target':''}" data-port-in="${esc(n.id)}" aria-label="Connect selected dependency to ${esc(n.label)}" title="Input: depends on another node"></button><button class="port out ${linkSource===n.id?'source':''}" data-port-out="${esc(n.id)}" aria-label="Use ${esc(n.label)} as a dependency source" title="Output: connect this to another node"></button></section>`;}).join('');}
function stats(){const nominal=availability(graph),conditional=failed.length?availability(graph,failed):nominal,base=availability(baseline),live=liveState(graph,failed);return `<section class="metrics" aria-label="Whole-system consequences"><div class="metric"><span class="metric-label">${failed.length?'With these components held down':'Whole-system availability'}</span><div class="metric-value"><strong class="${conditional===0?'bad':''}">${pct(conditional)}</strong></div><p class="metric-note">${failed.length?`${failed.length} fixed outage${failed.length===1?'':'s'}; other components remain uncertain.`:'Exact result from this dependency map.'}</p></div><div class="metric"><span class="metric-label">If everything else is up</span><div class="metric-value"><strong class="path-status ${live.success?'good':'bad'}">${live.success?'Output has a path':'Output is blocked'}</strong></div><p class="metric-note">${esc(node(graph.output).label)} · ${failed.length?'injected failures shown on the map':'try taking a component down'}</p>${failed.length?'<button class="button" id="restore-all">Restore all failures</button>':''}</div><div class="metric"><span class="metric-label">Nominal versus pinned baseline</span><div class="metric-value"><strong style="font-size:1.45rem">${pp(nominal-base)}</strong></div><p class="metric-note">${pct(nominal)} now · ${pct(base)} baseline · outages excluded</p><button class="button" id="pin-baseline">Pin current map as baseline</button></div></section>`;}
function instruction(){if(linkSource)return `Connect <strong>${esc(node(linkSource).label)}</strong> to another node’s left input port. Escape cancels.`;if(commonTargets)return `Add a shared requirement: choose <strong>${2-commonTargets.length} ${commonTargets.length?'more component':'components'}</strong> by their names.`;return 'Try failing Shared clock, then only Data feed A. Drag names; connect a right output port to a left input port.';}
function inspector(){const n=node(selected),rank=improvements(graph).filter(x=>x.gain>1e-9).slice(0,3),used=ancestors(graph);return `<section class="inspector-grid" aria-label="Edit selected node and inspect system"><div class="inspector-panel"><h2>Selected: ${esc(n.label)}</h2><label class="field-label" for="node-label">Name</label><input class="text-input" id="node-label" value="${esc(n.label)}" maxlength="60">${n.kind==='component'?`<div class="field-row"><label for="availability">Own availability</label><output id="availability-value">${(n.p*100).toFixed(1)}%</output></div><input class="availability-slider" id="availability" type="range" min="0" max="100" step="0.1" value="${n.p*100}"><p class="hint">This component must be up <em>and</em> every incoming dependency must pass.</p>`:`<div class="field-row"><label for="gate-mode">Pass rule</label><select id="gate-mode"><option value="OR" ${n.gate==='OR'?'selected':''}>ANY input (OR)</option><option value="AND" ${n.gate==='AND'?'selected':''}>ALL inputs (AND)</option></select></div><p class="hint">Gates have no independent failure chance. A gate with no inputs does not pass.</p>`}${!used.has(n.id)?'<p class="hint">This node does not currently affect the chosen system output.</p>':''}<div class="inspector-actions"><button class="button" id="make-output" ${graph.output===n.id?'disabled':''}>Use as system output</button><button class="button danger" id="delete-node" ${graph.output===n.id?'disabled':''}>Delete node</button></div></div><div class="inspector-panel"><h2>What ${esc(n.label)} needs</h2><div class="dependency-list">${n.inputs.length?n.inputs.map(id=>`<div class="dependency-item"><span>${esc(node(id).label)}</span><button class="button" data-unlink="${esc(id)}" aria-label="Remove ${esc(node(id).label)} dependency">×</button></div>`).join(''):`<p class="empty">${n.kind==='component'?'No dependencies. Only its own availability matters.':'No inputs yet. Connect at least one to make this gate useful.'}</p>`}</div><label class="field-label" for="dependency-source">Connect another dependency</label><div class="connect-row"><select id="dependency-source"><option value="">Choose a source</option>${graph.nodes.filter(s=>s.id!==n.id&&!n.inputs.includes(s.id)).map(s=>`<option value="${esc(s.id)}">${esc(s.label)}</option>`).join('')}</select><button class="button" id="connect-selected">Connect</button></div><p class="hint">Equivalent to connecting the source’s right port to this node’s left port. Cycles are rejected.</p></div><div class="inspector-panel improvement-panel"><h2>Which improvement reaches the output?</h2><p class="hint">Set one component’s own availability to 100%, holding the map and every other probability fixed.</p>${rank.length?rank.map(r=>`<div class="improvement"><div class="improvement-head"><button data-inspect="${esc(r.id)}">${esc(r.label)}</button><strong>${pp(r.gain)}</strong></div><div class="improvement-bar" aria-hidden="true"><i style="width:${r.gain/rank[0].gain*100}%"></i></div></div>`).join(''):'<p class="empty">No single component improvement increases this output. Check disconnected gates or multiple zero-availability requirements.</p>'}<p class="rank-note">Gains are percentage points of nominal system availability, not a cost-benefit ranking. Injected failures are excluded.</p></div></section>`;}
function lower(){return `<div class="bottom-row"><details><summary>How this model treats reliability</summary><p>Every component has an independent probability of being available at an unspecified observation or demand. A component also needs all its incoming dependencies. An ALL gate needs every input; an ANY gate needs at least one. Gates themselves do not fail.</p><p>The model enumerates every independent component state and evaluates the whole graph. A shared dependency is one component, reused wherever it appears. This captures that source of correlated path failure; other common causes and statistical correlations are absent unless you draw them explicitly.</p><p>Injecting a failure holds that component down and conditions the probability of the output on that outage. Other probabilities remain unchanged. Coloured paths show what can operate if every non-failed component is up; they are not a random simulation.</p><p>Adding an alternative copies the selected component’s incoming dependencies, adds an independent backup and an ANY gate, then routes the existing dependants through that gate. Shared upstream requirements remain shared. Connecting another dependency to a component adds an ALL requirement; changing a gate changes its pass rule.</p><p>Fictional inputs, no empirical calibration. No repair times, time dynamics, load sharing, fault detection, switching failures or physical battery behaviour. Keep the graph to ${LIMITS.nodes} nodes and ${LIMITS.components} uncertain components so exact enumeration remains small.</p></details><div class="bottom-actions"><button class="button" id="export">Export map & result</button><button class="button ghost" id="reset">Reset example</button></div></div><p class="save-note">${storageOK?'This map, injected failures and pinned baseline stay in this browser.':'Browser storage is unavailable; export to keep this map.'}</p>`;}
function render(focusId){const old=app.querySelector('.canvas-viewport'),scroll=old?{left:old.scrollLeft,top:old.scrollTop}:null;const live=liveState(graph,failed),used=ancestors(graph),size=dimensions();app.innerHTML=`${stats()}<div class="toolbar"><div class="toolbar-group"><label class="hidden-label" for="scenario">Example</label><select id="scenario"><option value="bess" ${scenario==='bess'?'selected':''}>Battery response</option><option value="service" ${scenario==='service'?'selected':''}>Online checkout</option></select><label class="hidden-label" for="new-kind">New node type</label><select id="new-kind"><option value="component">Component</option><option value="OR">ANY gate</option><option value="AND">ALL gate</option></select><button class="button" id="add-node" ${graph.nodes.length>=LIMITS.nodes?'disabled':''}>Add node</button><button class="button" id="add-alternative" ${node(selected).kind!=='component'||graph.nodes.length+2>LIMITS.nodes||graph.nodes.filter(n=>n.kind==='component').length>=LIMITS.components?'disabled':''}>Give selected a backup</button><button class="button ${commonTargets?'active':''}" id="add-common" ${graph.nodes.length>=LIMITS.nodes||graph.nodes.filter(n=>n.kind==='component').length>=LIMITS.components?'disabled':''}>Add shared dependency</button></div><div class="toolbar-group"><button class="button icon" id="undo" aria-label="Undo last change" ${!undo.length?'disabled':''}>↶ Undo</button><button class="button icon" id="redo" aria-label="Redo last change" ${!redo.length?'disabled':''}>↷ Redo</button></div></div>${message?`<div class="status-banner ${isError?'error':''}" ${isError?'role="alert"':''}>${esc(message)}</div>`:''}<section class="map-frame" aria-label="Editable dependency map"><div class="map-caption"><p class="map-instruction">${scenario==='service'&&!linkSource&&!commonTargets?'Try taking one service down, then Name service. Drag names; connect output ports to input ports.':instruction()}</p><button class="button" id="find-selected">Find selected</button></div><div class="canvas-viewport" tabindex="0" aria-label="Dependency canvas. Scroll to pan. Node names select; arrow keys move focused nodes."><div class="board" style="width:${size.width}px;height:${size.height}px"><svg class="links" width="${size.width}" height="${size.height}" aria-label="Dependencies"><defs><marker id="arrow-up" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M 0 0 L 6 3 L 0 6 Z" fill="#7094df"/></marker><marker id="arrow-down" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M 0 0 L 6 3 L 0 6 Z" fill="#d3949c"/></marker></defs><g class="edge-layer">${edges(live,used)}</g></svg>${renderNodes(live,used)}</div></div><div class="map-legend"><div class="legend-group"><span><i class="line-key"></i>Dependency available</span><span><i class="line-key down"></i>Dependency blocked</span></div><span>${graph.nodes.length}/${LIMITS.nodes} nodes · ${graph.nodes.filter(n=>n.kind==='component').length}/${LIMITS.components} components</span></div></section><p class="model-note">Click a line or use the selected node’s dependency list to unlink it. On small screens, swipe empty canvas to pan. Arrow keys move a focused node name; Shift moves farther.</p>${inspector()}${lower()}`;bind();if(scroll){const viewport=app.querySelector('.canvas-viewport');viewport.scrollLeft=scroll.left;viewport.scrollTop=scroll.top;}if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
function select(id){if(!node(id))throw Error('Choose an existing node.');if(commonTargets){if(node(id).kind!=='component')throw Error('A shared requirement must attach to components.');if(commonTargets.includes(id))return;commonTargets.push(id);if(commonTargets.length===2){const added=addCommonDependency(graph,commonTargets);selected=added.id;commit({graph:added.graph},'A new shared requirement now feeds both components. Change its availability or inject a failure.');findSelected();}else{render();announce('First component chosen. Choose one more.');}return;}selected=id;message='';isError=false;save();render();}
function findSelected(){const target=app.querySelector(`[data-node="${CSS.escape(selected)}"]`),viewport=app.querySelector('.canvas-viewport');if(!target)return;viewport.scrollTo({left:Math.max(0,node(selected).x-viewport.clientWidth/2+83),top:Math.max(0,node(selected).y-viewport.clientHeight/2+78),behavior:'instant'});}
function toggleFailure(id,value){const n=node(id);if(!n||n.kind!=='component')throw Error('Only components can have an injected failure.');const next=value===undefined?!failed.includes(id):value;if(typeof next!=='boolean')throw Error('Failed must be true or false.');if(next===failed.includes(id))return;commit({failed:next?[...failed,id]:failed.filter(x=>x!==id)},`${n.label} ${next?'is held failed':'is restored'}.`);}
function connectTo(target){if(!linkSource)throw Error('Choose a right output port first, or use the dependency selector below.');const source=linkSource;commit({graph:connect(graph,source,target)},`${node(source).label} is now required by ${node(target).label}.`);}
function exportMap(){const nominal=availability(graph),current=availability(graph,failed),rank=improvements(graph).slice(0,3);const text=`# A system of almost reliable parts\n\n${graph.name}\n\nOutput: ${node(graph.output).label}. Nominal availability: ${pct(nominal)}. With current injected failures: ${pct(current)}.\n\nHeld down: ${failed.length?failed.map(id=>node(id).label).join(', '):'none'}. Pinned nominal baseline: ${pct(availability(baseline))}.\n\n| Node | Own availability / rule | Dependencies |\n| --- | --- | --- |\n${graph.nodes.map(n=>`| ${n.label.replaceAll('|','/')} | ${n.kind==='component'?pct(n.p):n.gate==='AND'?'ALL':'ANY'} | ${n.inputs.map(id=>node(id).label.replaceAll('|','/')).join(', ')||'none'} |`).join('\n')}\n\n## If one component were made perfect\n\n${rank.map(r=>`- ${r.label}: ${pp(r.gain)} nominal system availability.`).join('\n')}\n\nIndependent component availability; shared nodes are counted once. Forced failures condition the calculation. Gates are deterministic. Fictional values, no time model or empirical calibration.\n\n## Map data\n\n\`\`\`json\n${JSON.stringify({graph,failed,baseline},null,2)}\n\`\`\`\n`;downloadText('reliability-map.md',text,'text/markdown;charset=utf-8');announce('Map and model results exported.');}
function bind(){
  document.querySelector('#scenario').addEventListener('change',e=>{const next=e.target.value,g=example(next);selected=g.nodes[0].id;commit({graph:g,baseline:clone(g),failed:[],scenario:next},'Example changed. Undo returns to your previous map.');});
  document.querySelector('#reset').addEventListener('click',()=>{const g=example(scenario);selected=g.nodes[0].id;commit({graph:g,baseline:clone(g),failed:[]},'Example reset. Undo keeps your previous work recoverable.');});
  document.querySelector('#undo').addEventListener('click',()=>{if(!undo.length)return;redo.push(snapshot());applySnapshot(undo.pop());message='Last change undone.';isError=false;save();render();announce(message);});
  document.querySelector('#redo').addEventListener('click',()=>{if(!redo.length)return;undo.push(snapshot());applySnapshot(redo.pop());message='Change restored.';isError=false;save();render();announce(message);});
  document.querySelector('#pin-baseline').addEventListener('click',()=>commit({baseline:clone(graph)},'Current nominal map pinned as the comparison baseline.'));
  document.querySelector('#restore-all')?.addEventListener('click',()=>commit({failed:[]},'All injected failures restored.'));
  document.querySelector('#add-node').addEventListener('click',()=>attempt(()=>{const added=addNode(graph,document.querySelector('#new-kind').value);selected=added.id;commit({graph:added.graph},'New node added. Connect it to make it part of the system.');findSelected();}));
  document.querySelector('#add-alternative').addEventListener('click',()=>attempt(()=>{const added=addAlternative(graph,selected);selected=added.id;commit({graph:added.graph},'Independent backup added through an ANY gate. It shares the original upstream dependencies.');findSelected();}));
  document.querySelector('#add-common').addEventListener('click',()=>{commonTargets=commonTargets?null:[];linkSource=null;message='';render();announce(commonTargets?'Choose two component names for the shared requirement.':'Shared dependency selection cancelled.');});
  document.querySelector('#find-selected').addEventListener('click',findSelected);
  document.querySelectorAll('[data-select]').forEach(b=>{b.addEventListener('click',()=>attempt(()=>select(b.dataset.select)));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const id=b.dataset.select,n=node(id),step=e.shiftKey?40:10;selected=id;const x=Math.max(20,n.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0)),y=Math.max(25,n.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0));commit({graph:updateNode(graph,id,{x,y})},'Node moved. Connections and probabilities are unchanged.');app.querySelector(`[data-select="${CSS.escape(id)}"]`)?.focus({preventScroll:true});});attachDrag(b);});
  document.querySelectorAll('[data-fail]').forEach(b=>b.addEventListener('click',()=>attempt(()=>toggleFailure(b.dataset.fail))));
  document.querySelectorAll('[data-port-out]').forEach(b=>b.addEventListener('click',()=>{linkSource=linkSource===b.dataset.portOut?null:b.dataset.portOut;commonTargets=null;message='';render();announce(linkSource?'Choose the target’s left input port.':'Connection cancelled.');}));
  document.querySelectorAll('[data-port-in]').forEach(b=>b.addEventListener('click',()=>attempt(()=>connectTo(b.dataset.portIn))));
  document.querySelectorAll('[data-edge-source]').forEach(path=>{const unlink=()=>attempt(()=>commit({graph:disconnect(graph,path.dataset.edgeSource,path.dataset.edgeTarget)},'Dependency removed. Undo restores it.'));path.addEventListener('click',unlink);path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();unlink();}});});
  document.querySelector('#node-label').addEventListener('change',e=>attempt(()=>{commit({graph:updateNode(graph,selected,{label:e.target.value.trim()})},'Node renamed.');document.querySelector('#node-label').focus();}));
  document.querySelector('#availability')?.addEventListener('input',e=>{document.querySelector('#availability-value').textContent=`${Number(e.target.value).toFixed(1)}%`;});
  document.querySelector('#availability')?.addEventListener('change',e=>attempt(()=>{commit({graph:updateNode(graph,selected,{p:Number(e.target.value)/100})},'Component availability changed.');document.querySelector('#availability').focus({preventScroll:true});}));
  document.querySelector('#gate-mode')?.addEventListener('change',e=>attempt(()=>commit({graph:updateNode(graph,selected,{gate:e.target.value})},'Gate rule changed.')));
  document.querySelector('#make-output').addEventListener('click',()=>attempt(()=>commit({graph:setOutput(graph,selected)},'System output changed.')));
  document.querySelector('#delete-node').addEventListener('click',()=>attempt(()=>commit({graph:removeNode(graph,selected)},'Node and its connections removed. Undo restores them.')));
  document.querySelectorAll('[data-unlink]').forEach(b=>b.addEventListener('click',()=>attempt(()=>commit({graph:disconnect(graph,b.dataset.unlink,selected)},'Dependency removed.'))));
  document.querySelector('#connect-selected').addEventListener('click',()=>attempt(()=>{const source=document.querySelector('#dependency-source').value;if(!source)throw Error('Choose a dependency source first.');commit({graph:connect(graph,source,selected)},'Dependency connected.');}));
  document.querySelectorAll('[data-inspect]').forEach(b=>b.addEventListener('click',()=>{select(b.dataset.inspect);findSelected();}));
  document.querySelector('#export').addEventListener('click',exportMap);
}
function attachDrag(handle){let drag=null;handle.addEventListener('pointerdown',e=>{if(e.button!==0||commonTargets)return;const n=node(handle.dataset.select);drag={id:n.id,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,before:snapshot(),moved:false};handle.setPointerCapture(e.pointerId);});handle.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(!drag.moved&&Math.hypot(dx,dy)<4)return;drag.moved=true;e.preventDefault();const n=node(drag.id);n.x=Math.max(20,Math.min(1850,drag.x+dx));n.y=Math.max(25,Math.min(850,drag.y+dy));const card=handle.closest('.node');card.classList.add('is-dragging');card.style.left=`${n.x}px`;card.style.top=`${n.y}px`;const size=dimensions(),board=app.querySelector('.board'),svg=app.querySelector('.links');board.style.width=`${size.width}px`;board.style.height=`${size.height}px`;svg.setAttribute('width',size.width);svg.setAttribute('height',size.height);app.querySelector('.edge-layer').innerHTML=edges(liveState(graph,failed),ancestors(graph));});const finish=e=>{if(!drag)return;const ended=drag;drag=null;if(ended.moved){undo.push(ended.before);undo=undo.slice(-30);redo=[];selected=ended.id;message='Layout changed. Dependencies stay connected.';isError=false;save();render();announce(message);}if(handle.hasPointerCapture?.(e.pointerId))handle.releasePointerCapture(e.pointerId);};handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',e=>{if(drag){applySnapshot(drag.before);drag=null;render();}if(handle.hasPointerCapture?.(e.pointerId))handle.releasePointerCapture(e.pointerId);});}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(linkSource||commonTargets)){linkSource=null;commonTargets=null;message='Selection cancelled.';isError=false;render();announce(message);}});
window.reliabilityExperiment={getState:()=>({graph:clone(graph),failed:[...failed],selected,nominal:availability(graph),conditioned:availability(graph,failed),baseline:availability(baseline),live:liveState(graph,failed)}),setFailure:(id,value)=>toggleFailure(id,value),connect:(source,target)=>commit({graph:connect(graph,source,target)},'Dependency connected.'),disconnect:(source,target)=>commit({graph:disconnect(graph,source,target)},'Dependency removed.'),select};
save();render();
let unregisterTools=registerTools(window.reliabilityExperiment);
window.addEventListener('pagehide',()=>unregisterTools());
window.addEventListener('pageshow',e=>{if(e.persisted)unregisterTools=registerTools(window.reliabilityExperiment);});
